function normalizeRecord(json) {
  if (!json) return null;

  if (Array.isArray(json.records)) {
    return json.records.map(normalizeRecord).filter(Boolean);
  }

  if (json.fields) {
    return {
      id: json.id || json.recordId,
      fields: json.fields,
    };
  }

  const { id, recordId, createdTime, ...rest } = json;

  return {
    id: id || recordId,
    fields: rest,
  };
}

function getRecords(nodeName) {
  const items = $items(nodeName) || [];
  const records = [];

  for (const item of items) {
    const normalized = normalizeRecord(item.json);

    if (Array.isArray(normalized)) {
      records.push(...normalized);
    } else if (normalized) {
      records.push(normalized);
    }
  }

  return records.filter((record) => record.id);
}

function asLinks(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value
      .map((item) => {
        if (typeof item === "string") return item;
        if (item?.id) return item.id;
        if (item?.recordId) return item.recordId;
        return String(item || "");
      })
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return [value.trim()].filter(Boolean);
  }

  return [];
}

function getString(value) {
  return String(value || "").trim();
}

function getNumber(value) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : null;
}

function percentToDisplay(value) {
  const numberValue = getNumber(value);

  if (numberValue === null) return "-";

  if (numberValue <= 1) {
    return `${Math.round(numberValue * 10000) / 100}%`;
  }

  return `${Math.round(numberValue * 100) / 100}%`;
}

const predictions = getRecords("GET High Risk Predictions");
const users = getRecords("GET Users");
const classes = getRecords("GET Classes");
const existingPlans = getRecords("GET Existing Intervention Plans");

const existingPlanText = existingPlans
  .map((plan) => getString(plan.fields.Ogretmen_Notu))
  .join("\n");

const output = [];

for (const prediction of predictions) {
  const studentId = asLinks(prediction.fields.Ogrenci)[0];
  const classId = asLinks(prediction.fields.Sinif)[0];

  if (!studentId || !classId) continue;

  const classRecord = classes.find((item) => item.id === classId);
  const student = users.find((item) => item.id === studentId);

  const teacherId = asLinks(classRecord?.fields?.Ogretmen)[0];

  if (!teacherId) continue;

  const teacher = users.find((item) => item.id === teacherId);

  const studentName = getString(student?.fields?.Ad_Soyad) || "Öğrenci";
  const teacherName = getString(teacher?.fields?.Ad_Soyad) || "Öğretmen";
  const teacherEmail = getString(teacher?.fields?.Eposta);

  const className =
    getString(classRecord?.fields?.Sinif_Adi) ||
    getString(classRecord?.fields?.Ders_Adi) ||
    "Sınıf";

  const riskLevel = getString(prediction.fields.Risk_Seviyesi) || "Yüksek";
  const predictionSummary = getString(prediction.fields.Ozet);
  const teacherVisible = getString(prediction.fields.Ogretmene_Gosterilecek);
  const studentVisible = getString(prediction.fields.Ogrenciye_Gosterilecek);
  const explanation1 = getString(prediction.fields.Aciklama_1);
  const explanation2 = getString(prediction.fields.Aciklama_2);
  const explanation3 = getString(prediction.fields.Aciklama_3);
  const predictedGrade = getNumber(prediction.fields.Tahmini_Donem_Notu);
  const passProbability = percentToDisplay(prediction.fields.Gecme_Olasiligi);

  const trackingCode = `MUDAHALE:TAHMIN:${prediction.id}:OGRETMEN:${teacherId}`;

  if (existingPlanText.includes(trackingCode)) {
    continue;
  }

  const dataSummary = [
    `Öğrenci: ${studentName}`,
    `Sınıf: ${className}`,
    `Öğretmen: ${teacherName}`,
    `Risk seviyesi: ${riskLevel}`,
    `Tahmini dönem notu: ${predictedGrade === null ? "-" : predictedGrade}`,
    `Geçme olasılığı: ${passProbability}`,
    "",
    "Tahmin özeti:",
    predictionSummary || "-",
    "",
    "Öğretmene gösterilecek analiz:",
    teacherVisible || "-",
    "",
    "Öğrenciye gösterilecek metin:",
    studentVisible || "-",
    "",
    "Ek açıklamalar:",
    explanation1 || "-",
    explanation2 || "-",
    explanation3 || "-",
    "",
    `Takip kodu: ${trackingCode}`,
  ].join("\n");

  const aiPrompt = `
Sen AkıllıSınıf AI erken uyarı sisteminde çalışan akademik müdahale planı motorusun.

Aşağıdaki yüksek riskli öğrenci tahminine göre öğretmen için uygulanabilir bir müdahale planı oluştur.

Veriler:
${dataSummary}

Kurallar:
- Sadece geçerli JSON döndür.
- Markdown kullanma.
- Dil Türkçe olsun.
- Plan destekleyici, akademik ve uygulanabilir olsun.
- Öğrenciyi suçlayıcı dil kullanma.
- 3 veya 4 müdahale adımı üret.
- Adım türleri şu değerlerden biri olsun: Rehberlik, Akademik Destek, Veli İletişimi, Takip.
- Süre gün sayısı 7 ile 30 arasında olsun.

JSON formatı:
{
  "hedef": "kısa hedef metni",
  "plan_ozeti": "öğretmen için kısa plan açıklaması",
  "ogretmen_notu": "öğretmene özel not",
  "sure_gun": 14,
  "adimlar": [
    {
      "adim_adi": "adım başlığı",
      "adim_turu": "Rehberlik",
      "aciklama": "ne yapılacağı",
      "son_gun": 3
    }
  ]
}
`;

  output.push({
    json: {
      trackingCode,
      predictionId: prediction.id,
      studentId,
      classId,
      teacherId,
      studentName,
      teacherName,
      teacherEmail,
      className,
      riskLevel,
      predictedGrade,
      passProbability,
      dataSummary,
      aiPrompt,
    },
  });
}

return output;

