function getString(value) {
  return String(value || "").trim();
}

function getNumber(value, fallback = 14) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : fallback;
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function stripJsonFence(text) {
  return getString(text)
    .replace(/^```json/i, "")
    .replace(/^```/i, "")
    .replace(/```$/i, "")
    .trim();
}

function parseAiJson(text) {
  const clean = stripJsonFence(text);

  try {
    return JSON.parse(clean);
  } catch {
    const match = clean.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch {
        return null;
      }
    }

    return null;
  }
}

function addDays(date, days) {
  const next = new Date(date);
  next.setDate(next.getDate() + days);
  return next.toISOString().slice(0, 10);
}

const inputItems = $items("Prepare Intervention Inputs");
const aiItems = $items("OpenRouter Intervention Plan");

const today = new Date().toISOString().slice(0, 10);
const output = [];

for (let index = 0; index < aiItems.length; index += 1) {
  const source = inputItems[index]?.json || {};
  const aiResponse = aiItems[index]?.json || {};

  const aiText =
    aiResponse.choices?.[0]?.message?.content ||
    aiResponse.body?.choices?.[0]?.message?.content ||
    "";

  const parsed = parseAiJson(aiText) || {};

  const durationDays = clamp(getNumber(parsed.sure_gun, 14), 7, 30);
  const endDate = addDays(today, durationDays);

  const goal =
    getString(parsed.hedef) ||
    `${source.studentName} için ${source.riskLevel} risk seviyesini azaltmak ve akademik takibi güçlendirmek.`;

  const planSummary =
    getString(parsed.plan_ozeti) ||
    "AI tarafından yüksek riskli öğrenci için müdahale planı oluşturuldu.";

  const teacherNote =
    getString(parsed.ogretmen_notu) ||
    "Öğrencinin durumu düzenli olarak izlenmeli ve gerekirse bireysel destek uygulanmalıdır.";

  let steps = Array.isArray(parsed.adimlar) ? parsed.adimlar : [];

  if (steps.length === 0) {
    steps = [
      {
        adim_adi: "Öğrenci ile kısa görüşme",
        adim_turu: "Rehberlik",
        aciklama: "Öğrencinin mevcut zorlandığı konular ve çalışma alışkanlıkları hakkında kısa görüşme yapılır.",
        son_gun: 3,
      },
      {
        adim_adi: "Eksik konu analizi",
        adim_turu: "Akademik Destek",
        aciklama: "Son notlar ve ödev verileri incelenerek eksik kazanımlar belirlenir.",
        son_gun: 7,
      },
      {
        adim_adi: "Takip değerlendirmesi",
        adim_turu: "Takip",
        aciklama: "Bir sonraki hafta öğrencinin gelişimi tekrar değerlendirilir.",
        son_gun: 14,
      },
    ];
  }

  output.push({
    json: {
      trackingCode: source.trackingCode,
      studentId: source.studentId,
      classId: source.classId,
      teacherId: source.teacherId,
      studentName: source.studentName,
      className: source.className,
      teacherName: source.teacherName,
      teacherEmail: source.teacherEmail,
      riskLevel: source.riskLevel,
      goal,
      planSummary,
      teacherNote,
      startDate: today,
      endDate,
      durationDays,
      steps: steps.slice(0, 4).map((step, stepIndex) => ({
        title:
          getString(step.adim_adi) ||
          `${stepIndex + 1}. Müdahale adımı`,
        type:
          getString(step.adim_turu) ||
          "Takip",
        description:
          getString(step.aciklama) ||
          "Öğrencinin akademik gelişimi için takip adımı uygulanır.",
        dueDate: addDays(today, clamp(getNumber(step.son_gun, 7), 1, 30)),
      })),
      fields: {
        Plan_Adi: `${source.studentName} - ${source.className} - Müdahale Planı`,
        Ogrenci: [source.studentId],
        Sinif: [source.classId],
        Ogretmen: [source.teacherId],
        Hedef: goal,
        Baslangic_Tarihi: today,
        Bitis_Tarihi: endDate,
        Durum: "Aktif",
        Basari_Durumu: "İzleniyor",
        Ogretmen_Notu:
          `${teacherNote}\n\nAI Plan Özeti:\n${planSummary}\n\nSistem takip kodu: ${source.trackingCode}`,
      },
    },
  });
}

return output;

const planInputItems = $items("Prepare Intervention Records");
const createdPlanItems = $items("CREATE Mudahale Planlari");

const output = [];

for (let index = 0; index < createdPlanItems.length; index += 1) {
  const source = planInputItems[index]?.json || {};
  const createdPlan = createdPlanItems[index]?.json || {};

  const planId = createdPlan.id || createdPlan.recordId;

  if (!planId) continue;

  const steps = Array.isArray(source.steps) ? source.steps : [];

  for (const step of steps) {
    output.push({
      json: {
        trackingCode: source.trackingCode,
        teacherEmail: source.teacherEmail,
        teacherName: source.teacherName,
        studentName: source.studentName,
        className: source.className,
        riskLevel: source.riskLevel,
        planId,
        fields: {
          Adim_Adi: step.title,
          Plan: [planId],
          Sorumlu: [source.teacherId],
          Adim_Turu: step.type,
          Aciklama: step.description,
          Son_Tarih: step.dueDate,
          Durum: "Planlandı",
        },
      },
    });
  }
}

return output;

